<?php
$pdo=db();$manager=in_array($user['role'],['Administrator','Head'],true);$tab=(string)($_GET['tab']??($user['role']==='Guardian'?'family':'notices'));if(!in_array($tab,['notices','calendar','family'],true)||($tab==='family'&&$user['role']!=='Guardian'))$tab='notices';$visibleAudiences=$user['role']==='Guardian'?['Everyone','Guardians']:['Everyone','Staff'];if($manager)$visibleAudiences=['Everyone','Staff','Guardians'];$in=implode(',',array_fill(0,count($visibleAudiences),'?'));
$editNoticeId=filter_var($_GET['edit_notice']??null,FILTER_VALIDATE_INT);$editNotice=null;if($manager&&$editNoticeId){$q=$pdo->prepare('SELECT * FROM announcements WHERE id=:id');$q->execute(['id'=>$editNoticeId]);$editNotice=$q->fetch()?:null;}
$viewId=filter_var($_GET['view']??null,FILTER_VALIDATE_INT);$viewNotice=null;if($viewId){$sql='SELECT a.*,u.full_name AS author,(r.user_id IS NOT NULL) AS is_read FROM announcements a LEFT JOIN users u ON u.id=a.created_by LEFT JOIN announcement_reads r ON r.announcement_id=a.id AND r.user_id=? WHERE a.id=? AND a.status=\'Published\' AND a.published_at<=NOW() AND a.audience IN ('.$in.')';$q=$pdo->prepare($sql);$q->execute(array_merge([(int)$user['id'],$viewId],$visibleAudiences));$viewNotice=$q->fetch()?:null;if(!$viewNotice&&!$manager)http_response_code(404);}
$statusFilter=(string)($_GET['status']??($manager?'Published':'Published'));if(!in_array($statusFilter,['Draft','Published','Archived','All'],true))$statusFilter='Published';$listSql='SELECT a.*,u.full_name AS author,(r.user_id IS NOT NULL) AS is_read FROM announcements a LEFT JOIN users u ON u.id=a.created_by LEFT JOIN announcement_reads r ON r.announcement_id=a.id AND r.user_id=? WHERE 1=1';$listParams=[(int)$user['id']];if($manager){if($statusFilter!=='All'){$listSql.=' AND a.status=?';$listParams[]=$statusFilter;}}else{$listSql.=' AND a.status=\'Published\' AND a.published_at<=NOW() AND a.audience IN ('.$in.')';$listParams=array_merge($listParams,$visibleAudiences);}$listSql.=' ORDER BY COALESCE(a.published_at,a.created_at) DESC,a.id DESC LIMIT 100';$q=$pdo->prepare($listSql);$q->execute($listParams);$notices=$q->fetchAll();
$editEventId=filter_var($_GET['edit_event']??null,FILTER_VALIDATE_INT);$editEvent=null;if($manager&&$editEventId){$q=$pdo->prepare('SELECT * FROM school_events WHERE id=:id');$q->execute(['id'=>$editEventId]);$editEvent=$q->fetch()?:null;}
$eventSql='SELECT e.*,u.full_name AS author FROM school_events e LEFT JOIN users u ON u.id=e.created_by WHERE e.starts_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)';$eventParams=[];if($manager){$eventSql.=" AND e.status<>'Cancelled'";}else{$eventSql.=" AND e.status='Published' AND e.audience IN (".$in.")";$eventParams=$visibleAudiences;}$eventSql.=' ORDER BY e.starts_at LIMIT 100';$q=$pdo->prepare($eventSql);$q->execute($eventParams);$events=$q->fetchAll();
?>
<div class="page-heading"><div><div class="eyebrow">SCHOOL COMMUNITY</div><h1>Messages & calendar</h1><p class="subheading">Share school notices and publish term events to staff and guardians.</p></div></div>
<div class="settings-tabs"><?php if($user['role']==='Guardian'): ?><a class="<?= $tab==='family'?'selected':'' ?>" href="?page=communications&tab=family">My learners</a><?php endif; ?><a class="<?= $tab==='notices'?'selected':'' ?>" href="?page=communications&tab=notices">Announcements</a><a class="<?= $tab==='calendar'?'selected':'' ?>" href="?page=communications&tab=calendar">School calendar</a></div>
<?php if($viewNotice): ?><article class="panel announcement-detail"><div class="announcement-meta"><span class="priority-pill priority-<?= strtolower(h($viewNotice['priority'])) ?>"><?= h($viewNotice['priority']) ?></span><span><?= h($viewNotice['audience']) ?></span><span><?= h(date('d M Y H:i',strtotime($viewNotice['published_at']))) ?></span></div><h2><?= h($viewNotice['title']) ?></h2><p class="announcement-author">Posted by <?= h($viewNotice['author']?:'School administration') ?></p><div class="announcement-body"><?= nl2br(h($viewNotice['body'])) ?></div><div class="form-actions"><a class="outline-button" href="?page=communications&tab=notices">Back to announcements</a><?php if(!$viewNotice['is_read']): ?><form method="post" action="actions/announcement_read.php"><?= csrf_field() ?><input type="hidden" name="announcement_id" value="<?= (int)$viewId ?>"><button class="primary-button">Mark as read</button></form><?php endif; ?></div></article>
<?php elseif($tab==='family'&&$user['role']==='Guardian'): require __DIR__ . '/family_portal.php'; elseif($tab==='notices'): ?>
  <?php if($manager): ?><section class="panel settings-panel"><h2><?= $editNotice?'Edit announcement':'Write an announcement' ?></h2><p>Published notices are visible to the selected audience. Drafts are private to school administrators and heads.</p><form method="post" action="actions/announcement_save.php" class="settings-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($editNotice['id']??0) ?>"><div class="settings-grid"><label>Title<input name="title" maxlength="180" required value="<?= h($editNotice['title']??'') ?>"></label><label>Audience<select name="audience"><?php foreach(['Everyone','Staff','Guardians'] as $audience): ?><option <?= ($editNotice['audience']??'Everyone')===$audience?'selected':'' ?>><?= h($audience) ?></option><?php endforeach; ?></select></label><label>Priority<select name="priority"><?php foreach(['Normal','Important','Urgent'] as $priority): ?><option <?= ($editNotice['priority']??'Normal')===$priority?'selected':'' ?>><?= h($priority) ?></option><?php endforeach; ?></select></label><label class="full-width">Message<textarea name="body" rows="5" maxlength="10000" required><?= h($editNotice['body']??'') ?></textarea></label></div><div class="form-actions"><button class="outline-button" name="status" value="Draft">Save draft</button><button class="primary-button" name="status" value="Published">Publish now</button><?php if($editNotice): ?><a class="text-button" href="?page=communications&tab=notices">Cancel edit</a><?php endif; ?></div></form></section><?php endif; ?>
  <?php if($manager): ?><form class="report-filter" method="get"><input type="hidden" name="page" value="communications"><input type="hidden" name="tab" value="notices"><label>Show<select name="status"><?php foreach(['Published','Draft','Archived','All'] as $status): ?><option <?= $statusFilter===$status?'selected':'' ?>><?= h($status) ?></option><?php endforeach; ?></select></label><button class="outline-button">Filter</button></form><?php endif; ?>
  <section class="panel learners-panel"><div class="panel-heading"><div><h2><?= $manager&&$statusFilter==='Draft'?'Draft announcements':($statusFilter==='Archived'?'Archived announcements':'School announcements') ?></h2><p><?= count($notices) ?> shown</p></div></div><div class="announcement-list"><?php foreach($notices as $notice): ?><article class="announcement-row"><div class="announcement-row-mark <?= strtolower(h($notice['priority'])) ?>">◌</div><div class="announcement-copy"><div class="announcement-meta"><span class="priority-pill priority-<?= strtolower(h($notice['priority'])) ?>"><?= h($notice['priority']) ?></span><span><?= h($notice['audience']) ?></span><span><?= h($notice['status']) ?></span><?php if(!$notice['is_read']&&$notice['status']==='Published'): ?><b class="unread-label">Unread</b><?php endif; ?></div><h3><?= h($notice['title']) ?></h3><p><?= h(mb_strimwidth(strip_tags($notice['body']),0,220,'…')) ?></p><small>By <?= h($notice['author']?:'School administration') ?> · <?= h(date('d M Y H:i',strtotime($notice['published_at']?:$notice['created_at']))) ?></small></div><div class="announcement-actions"><?php if($notice['status']==='Published'&&$notice['published_at']&&strtotime($notice['published_at'])<=time()): ?><a class="text-button" href="?page=communications&tab=notices&view=<?= (int)$notice['id'] ?>">Read →</a><?php endif; ?><?php if($manager&&$notice['status']!=='Archived'): ?><a class="text-button" href="?page=communications&tab=notices&edit_notice=<?= (int)$notice['id'] ?>">Edit</a><form method="post" action="actions/announcement_save.php"><?= csrf_field() ?><input type="hidden" name="operation" value="archive"><input type="hidden" name="id" value="<?= (int)$notice['id'] ?>"><button class="text-button">Archive</button></form><?php endif; ?></div></article><?php endforeach; if(!$notices): ?><div class="empty-state"><h2>No announcements here yet</h2><p>Published notices for your audience will appear in this list.</p></div><?php endif; ?></div></section>
<?php else: ?>
  <?php if($manager): ?><section class="panel settings-panel"><h2><?= $editEvent?'Edit school event':'Add a school event' ?></h2><form method="post" action="actions/school_event_save.php" class="inline-form fee-schedule-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($editEvent['id']??0) ?>"><label>Event title<input name="title" required maxlength="180" value="<?= h($editEvent['title']??'') ?>"></label><label>Starts<input type="datetime-local" name="starts_at" required value="<?= $editEvent?date('Y-m-d\TH:i',strtotime($editEvent['starts_at'])):'' ?>"></label><label>Ends<input type="datetime-local" name="ends_at" value="<?= !empty($editEvent['ends_at'])?date('Y-m-d\TH:i',strtotime($editEvent['ends_at'])):'' ?>"></label><label>Venue<input name="venue" maxlength="120" value="<?= h($editEvent['venue']??'') ?>" placeholder="Optional"></label><label>Audience<select name="audience"><?php foreach(['Everyone','Staff','Guardians'] as $audience): ?><option <?= ($editEvent['audience']??'Everyone')===$audience?'selected':'' ?>><?= h($audience) ?></option><?php endforeach; ?></select></label><label>Description<textarea name="description" rows="2" maxlength="5000"><?= h($editEvent['description']??'') ?></textarea></label><button class="primary-button" name="status" value="Published">Publish event</button><button class="outline-button" name="status" value="Draft">Save draft</button></form></section><?php endif; ?>
  <section class="panel learners-panel"><div class="panel-heading"><div><h2>School calendar</h2><p>Upcoming events and the recent school calendar</p></div></div><div class="announcement-list calendar-list"><?php foreach($events as $event): ?><article class="calendar-event"><div class="calendar-date"><b><?= h(date('d',strtotime($event['starts_at']))) ?></b><span><?= h(date('M',strtotime($event['starts_at']))) ?></span></div><div class="announcement-copy"><div class="announcement-meta"><span><?= h($event['audience']) ?></span><span><?= h($event['status']) ?></span></div><h3><?= h($event['title']) ?></h3><p><?= nl2br(h($event['description']??'')) ?></p><small><?= h(date('l, d M Y · H:i',strtotime($event['starts_at']))) ?><?= $event['ends_at']?' – '.h(date('H:i',strtotime($event['ends_at']))):'' ?><?= $event['venue']?' · '.h($event['venue']):'' ?></small></div><?php if($manager): ?><div class="announcement-actions"><a class="text-button" href="?page=communications&tab=calendar&edit_event=<?= (int)$event['id'] ?>">Edit</a><?php if($event['status']==='Published'): ?><form method="post" action="actions/school_event_save.php"><?= csrf_field() ?><input type="hidden" name="operation" value="cancel"><input type="hidden" name="id" value="<?= (int)$event['id'] ?>"><button class="text-button">Cancel event</button></form><?php endif; ?></div><?php endif; ?></article><?php endforeach; if(!$events): ?><div class="empty-state"><h2>No school events listed</h2><p>Published events will appear here for their intended audience.</p></div><?php endif; ?></div></section>
<?php endif; ?>
